import{seamAt}from'./map-seams.js';
import{gateEditor}from'./gate-editor.js';
import {checkGatePosition,clearGateWalls,moveGate,removeGate} from './gate-placement.js';
import{gateInteractsAt,gateMasks,validateGateMasks}from'./gate-cells.js';
import{HMS,LEDGES,fieldAt,ledgeAt,canUseHM,newFieldPreview,clearFieldPreview,waterAt}from'./field-model.js';
import{RULES,movementAt,setMovement,paintWall,wallRectangle,addPortal,portalAt,gateBounds,wrapDialogue}from'./world-model.js';
import{uid,inBounds}from'./model.js';
import{movementPanel,movementBrush,inspectMovement,fillMovement}from'./movement-ui.js';
export function worldWorkshop(api,builtin){
 const $=s=>document.querySelector(s),esc=api.esc,map=api.map,project=api.project;
 const state={tab:'walls',wallId:builtin.walls?.[0]?.id,erase:false,shape:'line',rule:'block',elevation:null,collision:null,behavior:null,overlayType:'rules',overlayOpacity:.45,overlay:false,pendingPortal:null,play:null,facing:{x:0,y:1}};
 const walls=()=>api.library.list('wallStyles',project()),gates=()=>api.library.list('gateStyles',project());
 const editor=gateEditor({...api,styles:gates,saved:(style,placed)=>{state.gateId=style.id;if(!placed)api.mode('gate');api.refresh();}});
 const keep=(key,item)=>api.library.attach(project(),key,item);
 const thumb=(a,alt)=>`<img class="smart-thumb" src="${esc(a)}" alt="${esc(alt)}">`;
 function open(tab=state.tab){if(tab==='portals'){api.doors().open();return;}state.tab=tab;api.modal('Walls & world rules',`<div class="smart-tabs world-tabs">${[['walls','Walls'],['movement','Movement'],['portals','Portals'],['dialogue','Dialogue'],['gates','Gates'],['field','HMs & ledges'],['test','Playtest']].map(([k,n])=>`<button type="button" data-world-tab="${k}" class="${k===tab?'active':''}">${n}</button>`).join('')}</div><div id="worldContent"></div>`);$('#dialogFooter').hidden=false;$('#submitDialog').hidden=true;$('#cancelDialog').textContent='Done';document.querySelectorAll('[data-world-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.worldTab;render();});render();}
 function render(){document.querySelectorAll('[data-world-tab]').forEach(b=>b.classList.toggle('active',b.dataset.worldTab===state.tab));const t=$('#worldContent');if(state.tab==='walls'){
 t.innerHTML=`<p>Walls join as you draw and block walking at their base. Enclosure styles supply real turning pieces. Erasing a wall restores the terrain below it.</p><div class="smart-actions"><button id="makeWall" type="button">Save selected strip as a wall</button><button id="eraseWalls" type="button">Erase walls</button></div><div class="smart-cards">${walls().map(w=>`<article class="smart-card">${w.preview?thumb(w.preview,w.name):''}<strong>${esc(w.name)}</strong><small>${w.junctions?'S bends · T and cross joins':w.axis==='horizontal'?'Horizontal runs · automatic ends':'Corners & vertical sides · enclosures'}</small><div class="smart-actions"><button type="button" data-wall="${esc(w.id)}">Draw line</button>${w.perimeter?`<button type="button" data-wall-box="${esc(w.id)}">Draw enclosure</button>`:''}<button type="button" data-wall-copy="${esc(w.id)}">Duplicate / rename</button></div></article>`).join('')}</div>`;
 const choose=(id,shape)=>{state.wallId=id;state.shape=shape;state.erase=false;api.change(()=>keep('wallStyles',walls().find(w=>w.id===id)));api.mode(shape==='box'?'wallbox':'wall');api.close();api.toast(shape==='box'?'Drag the enclosure outline. Corners and side pieces fit automatically.':'Wall brush ready. Drag a line; the ends update automatically.');};document.querySelectorAll('[data-wall]').forEach(b=>b.onclick=()=>choose(b.dataset.wall,'line'));document.querySelectorAll('[data-wall-box]').forEach(b=>b.onclick=()=>choose(b.dataset.wallBox,'box'));document.querySelectorAll('[data-wall-copy]').forEach(b=>b.onclick=()=>renameWall(walls().find(w=>w.id===b.dataset.wallCopy)));$('#makeWall').onclick=makeWall;$('#eraseWalls').onclick=()=>{state.erase=true;api.mode('wall');api.close();api.toast('Drag across wall bases to remove them.');};
 }else if(state.tab==='movement'){
 movementPanel({...api,draw:api.draw||api.refresh},state,t,api.close);
 }else if(state.tab==='portals'){api.doors().open();return;
 const list=project().links.filter(l=>l.runtime?.type==='portal');t.innerHTML=`<p>Tap the departure tile, choose a map, then tap the arrival tile. Two-way portals create and link both ends together. These become playable warp events in a ROM export.</p><button type="button" id="beginPortal" class="primary">Link two tiles</button>${list.map(l=>`<div class="world-row"><span><b>${esc(l.label)}</b><small>${esc(project().maps.find(m=>m.id===l.from.mapId)?.name)} ${l.from.x},${l.from.y} ${l.twoWay?'↔':'→'} ${esc(project().maps.find(m=>m.id===l.to.mapId)?.name)} ${l.to.x},${l.to.y}</small></span><button type="button" data-edit-portal="${esc(l.id)}">Edit</button><button type="button" data-remove-portal="${esc(l.id)}">Remove</button></div>`).join('')}`;$('#beginPortal').onclick=()=>{state.pendingPortal={};api.mode('portal');api.close();api.toast('Tap the departure tile for this portal.');};document.querySelectorAll('[data-remove-portal]').forEach(b=>b.onclick=()=>{api.change(()=>project().links=project().links.filter(l=>l.id!==b.dataset.removePortal));render();api.refresh();});document.querySelectorAll('[data-edit-portal]').forEach(b=>b.onclick=()=>api.link(project().links.find(l=>l.id===b.dataset.editPortal)));
 }else if(state.tab==='dialogue'){
 t.innerHTML=`<p>Place an interaction on a sign, object or other map tile. The player faces it and presses A. Imported NPCs can keep their original scripts or use your replacement dialogue.</p><button type="button" id="placeDialogue" class="primary">Add interaction dialogue</button><p class="hint-line">Text wraps into two-line game pages. Ordinary note pins stay as instructions until “Use this as in-game dialogue” is enabled.</p>${map().markers.filter(n=>n.runtime).map(n=>`<div class="world-row"><span><b>${esc(n.title)}</b><small>${n.x},${n.y} · ${esc((n.runtime.text||n.text||'Ordered event').slice(0,70))}</small></span><button type="button" data-edit-talk="${esc(n.id)}">Edit</button></div>`).join('')}`;$('#placeDialogue').onclick=()=>{api.mode('talk');api.close();api.toast('Tap the object or sign tile to give it dialogue.');};document.querySelectorAll('[data-edit-talk]').forEach(b=>b.onclick=()=>{const n=map().markers.find(n=>n.id===b.dataset.editTalk);if(n.runtime?.action==='sequence')api.editEvent?.(n);else api.dialogue(n.x,n.y,n,true);});
 }else if(state.tab==='gates'){
 t.innerHTML=`<p>Face the opening tile and press A. Horizontal gates cross north–south paths; vertical gates cross east–west paths. The opening becomes walkable; outer posts stay solid. Gates reset when you leave or reload the map and use no story flags.</p><div class="smart-actions"><button id="customGate" type="button">Make a custom gate</button></div><div class="smart-cards">${gates().map(g=>{const a=api.asset(g.closedAssetId);return`<article class="smart-card">${thumb(a.data||a.src,g.name)}<strong>${esc(g.name)}</strong><small>${g.w} × ${g.h} tiles · opening on interaction</small><div class="smart-actions"><button type="button" data-gate-style="${esc(g.id)}">Place gate</button><button type="button" data-gate-customize="${esc(g.id)}">Customize</button></div></article>`;}).join('')}</div>${(map().gates||[]).map(g=>`<div class="world-row"><span><b>${esc(g.name)}</b><small>${g.x},${g.y}</small></span><button type="button" data-edit-gate="${esc(g.id)}">Edit</button></div>`).join('')}`;document.querySelectorAll('[data-gate-style]').forEach(b=>b.onclick=()=>{state.gateId=b.dataset.gateStyle;api.mode('gate');api.close();api.toast('Tap where the opening should go. The posts fit around it.');});document.querySelectorAll('[data-gate-customize]').forEach(b=>b.onclick=()=>editor.open(gates().find(g=>g.id===b.dataset.gateCustomize)));document.querySelectorAll('[data-edit-gate]').forEach(b=>b.onclick=()=>gateDialog(map().gates.find(g=>g.id===b.dataset.editGate)));$('#customGate').onclick=customGate;
 }else if(state.tab==='field'){api.field().open();return;}else{
 t.innerHTML=`<p>Check your authored movement, foreground, portals, dialogue and gate openings before exporting. Use the GBA playtester to check the actual game as well.</p><div class="smart-actions"><button id="startPlay" type="button" class="primary">Quick play check</button><button id="fullROMPlay" type="button">Play edited GBA</button><button id="hmPlayOptions" type="button">HM test options</button></div><button id="stopPlay" type="button">Stop play check</button><p class="hint-line">Tap a nearby tile to move, or use the direction buttons / keyboard arrows. A interacts with the facing tile. Face water and press A to Surf when the test player has Surf and its badge.</p>`;$('#fullROMPlay').onclick=api.playROM;$('#hmPlayOptions').onclick=()=>api.field().open('test');$('#startPlay').onclick=()=>{api.close();startPlay();};$('#stopPlay').onclick=()=>{stopPlay();api.close();};}
 }
 function renameWall(w){api.modal('Save wall copy',`<label>Name<input id="wallName" value="${esc(w.name+' copy')}" maxlength="100"></label>`,async()=>{const copy={...structuredClone(w),id:uid(),name:$('#wallName').value.trim()||w.name+' copy'};await api.library.save('wallStyles',copy,api.asset);api.toast('Wall saved to My library.');},'Save wall');}
 function makeWall(){const b=api.brush(),a=api.asset(b.assetId);if(b.cols<3||b.rows>8){api.toast('Select a strip at least three tiles wide and up to eight tiles tall: left end, middle, right end.');return;}api.modal('Save horizontal wall',`<p>The first, middle and last column become automatically joined wall pieces. The bottom row blocks walking. Select the entire height of the wall in the tileset first.</p><label>Name<input id="wallName" value="${esc(a.name+' wall')}" maxlength="100"></label>`,async()=>{const captured=await api.captureSelection(),source=captured.image,cols=b.cols,h=source.height,atlas=document.createElement('canvas');atlas.width=64;atlas.height=h*4;const ctx=atlas.getContext('2d'),original=document.createElement('canvas');original.width=source.width;original.height=h;original.getContext('2d').putImageData(source,0,0);[0,Math.floor(cols/2),cols-1].forEach((col,i)=>ctx.drawImage(original,col*16,0,16,h,i*16,0,16,h));ctx.drawImage(original,0,0,8,h,48,0,8,h);ctx.drawImage(original,cols*16-8,0,8,h,56,0,8,h);const id=uid(),asset={id,name:$('#wallName').value.trim()||'Custom wall',width:atlas.width,height:atlas.height,tileSize:16,data:atlas.toDataURL('image/png'),category:'Walls'},roles={end_w:{sx:0,sy:0},horizontal:{sx:16,sy:0},end_e:{sx:32,sy:0},isolated:{sx:48,sy:0}},variants=Array.from({length:16},(_,m)=>roles[(m&10)===10?'horizontal':m&2?'end_w':m&8?'end_e':'isolated']),definition={id:uid(),assetId:id,name:asset.name,category:'My walls',axis:'horizontal',sw:16,sh:h,roles,variants};await api.library.save('wallStyles',definition,api.asset,[asset]);api.change(()=>keep('wallStyles',definition));state.wallId=definition.id;state.erase=false;state.shape='line';api.mode('wall');api.toast('Wall saved across projects. Drag to draw it.');},'Save wall');}
 function customGate(){return editor.open();}

 function gateDialog(existing,x,y){
  const style=existing||gates().find(g=>g.id===state.gateId)||gates()[0];if(!style)throw Error('Choose a gate first.');
  api.modal(existing?'Edit operational gate':'Place operational gate',`<p>${esc(style.name)} · ${style.w} × ${style.h} tiles. The gate opens on A and resets when you leave.</p><label>Name<input id="gateName" maxlength="100" value="${esc(style.name)}"></label>${existing?`<div class="field-row"><label>Left tile X<input id="gateX" type="number" min="0" max="${map().width-style.w}" value="${existing.x}"></label><label>Base tile Y<input id="gateY" type="number" min="${style.h-1}" max="${map().height-1}" value="${existing.y}"></label></div><button id="moveGateOnMap" type="button">Move gate on map</button>`:''}<label>Opening dialogue (optional)<textarea id="gateText" maxlength="4000" placeholder="The gate swings open…">${esc(existing?.text||'')}</textarea></label>${existing?'<button id="editGateArtwork" type="button">Edit artwork & opening</button><button id="deleteGate" type="button" class="danger">Delete gate</button>':''}`,()=>{
   if(!existing&&(map().gates?.length||0)>=64)throw Error('Use at most 64 gates on a map.');const anchor=style.placementAnchor,g=existing||{...structuredClone(style),id:uid(),styleId:style.id,x:anchor?x-anchor.x:x,y:anchor?y-anchor.y+style.h-1:y},nx=existing?+$('#gateX').value:g.x,ny=existing?+$('#gateY').value:g.y;
   checkGatePosition(map(),g,nx,ny);if($('#gateText').value.trim())wrapDialogue($('#gateText').value);
   api.change(()=>{if(existing)moveGate(map(),g,nx,ny);else{keep('gateStyles',style);map().gates??=[];map().gates.push(g);clearGateWalls(map(),g);}g.name=$('#gateName').value.trim()||style.name;g.text=$('#gateText').value.trim();});api.refresh();
  },existing?'Save gate':'Place gate');
  if(existing){$('#moveGateOnMap').onclick=()=>{api.close();api.focusGate?.(existing);api.toast('Drag any part of the selected gate to move it.');};$('#editGateArtwork').onclick=()=>editor.open(existing,existing);$('#deleteGate').onclick=()=>{api.change(()=>removeGate(map(),existing));api.close();api.refresh();};}
 }
 function portalTap(x,y){const pending=state.pendingPortal||{};if(!pending.from){pending.from={mapId:map().id,x,y};state.pendingPortal=pending;api.modal('Choose the arrival map',`<p>Departure: ${esc(map().name)} · ${x},${y}. Next, choose a map and tap its arrival tile.</p><label>Destination map<select id="portalTargetMap">${project().maps.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select></label>`,()=>{pending.target=$('#portalTargetMap').value;api.loadMap(pending.target);api.mode('portal');api.toast('Tap the arrival tile.');},'Pick arrival tile');return;}if(pending.target&&map().id!==pending.target){api.toast('Choose an arrival on the selected destination map.');return;}const to={mapId:map().id,x,y};api.modal('Link this portal',`<p>${esc(project().maps.find(m=>m.id===pending.from.mapId)?.name)} ${pending.from.x},${pending.from.y} → ${esc(map().name)} ${x},${y}</p><label>Name<input id="portalName" value="Portal" maxlength="80"></label><label class="check"><input id="portalTwoWay" type="checkbox" checked> Create the return portal too</label><p>Step-on portals work on ordinary floor and do not require animated door art.</p>`,()=>{api.change(()=>{addPortal(project(),pending.from,to,{twoWay:$('#portalTwoWay').checked,label:$('#portalName').value.trim()||'Portal'});for(const p of[pending.from,to])setMovement(project().maps.find(m=>m.id===p.mapId),p.x,p.y,{mode:'walk'});});state.pendingPortal=null;api.mode('move');api.refresh();api.toast('Portal linked. Try it in Play check or export the ROM.');},'Link portal');}
 function startPlay(){let at=null;for(let y=0;y<map().height&&!at;y++)for(let x=0;x<map().width;x++)if(!movementAt(map(),x,y).collision){at={x,y};break;}if(!at){api.toast('This map has no walkable starting tile. Paint one in Movement.');return;}state.play=newFieldPreview(map().id,at);api.mode('play');api.arrival?.('enter');$('#playDock').hidden=false;api.refresh();api.toast('Play check: tap an adjacent tile to walk, or use arrows and A.');}
 function stopPlay(){state.play=null;$('#playDock').hidden=true;if(api.tool()==='play')api.mode('move');api.refresh();}
 function step(dx,dy){const p=state.play;if(!p||api.eventBusy?.())return;state.facing={x:dx,y:dy};let x=p.x+dx,y=p.y+dy;const seam=seamAt(project(),map().id,x,y);if(seam){const target=project().maps.find(m=>m.id===seam.to.mapId),r=movementAt(target,seam.to.x,seam.to.y,{openGates:p.openGates,fieldState:p});if(r.collision||waterAt(target,seam.to.x,seam.to.y)&&!p.surfing){api.toast('The connected edge is blocked.');return;}api.loadMap(target.id,true);Object.assign(p,{mapId:target.id,x:seam.to.x,y:seam.to.y});const surfing=p.surfing;clearFieldPreview(p,map());p.surfing=surfing&&waterAt(map(),p.x,p.y);api.arrival?.('seam');api.refresh();return;}const object=fieldAt(map(),x,y,p);if(object?.kind==='strength'&&p.strength){const nx=x+dx,ny=y+dy,r=movementAt(map(),nx,ny,{openGates:p.openGates,fieldState:p});if(r.collision||waterAt(map(),nx,ny)||ledgeAt(map(),nx,ny)){api.toast('The boulder needs a clear tile behind it.',1300);return;}p.fieldPositions.set(object.id,{x:nx,y:ny});}
 const ledge=ledgeAt(map(),x,y);if(ledge){const d=LEDGES[ledge];if(d.dx!==dx||d.dy!==dy){api.toast('This ledge only permits '+d.name.toLowerCase()+'.',1200);return;}x+=dx;y+=dy;}
 const r=movementAt(map(),x,y,{openGates:p.openGates,fieldState:p}),water=waterAt(map(),x,y),portalCell=portalAt(project(),map().id,x,y);if(!portalCell&&(r.collision||water&&!p.surfing)){api.toast('Blocked'+(water?' · face the water and use Surf.':'.'),1200);api.refresh();return;}p.x=x;p.y=y;if(!water)p.surfing=false;const portal=portalAt(project(),map().id,x,y);if(portal){api.loadMap(portal.to.mapId,true);p.mapId=portal.to.mapId;p.x=portal.to.x;p.y=portal.to.y;clearFieldPreview(p,map());const facing=portal.link.runtime?.[portal.to===portal.link.to?'arrivalFacing':'returnFacing'];if(facing&&facing!=='auto')state.facing={north:{x:0,y:-1},south:{x:0,y:1},west:{x:-1,y:0},east:{x:1,y:0}}[facing];api.arrival?.('portal');}api.refresh();const events=api.eventAt?.(p.x,p.y,'step')||[];if(events.length)(async()=>{for(const event of events)await api.runEvent?.(event);})();}
 function interact(){const p=state.play;if(!p||api.eventBusy?.())return;const x=p.x+state.facing.x,y=p.y+state.facing.y,object=fieldAt(map(),x,y,p);if(object){if(!canUseHM(object.kind,p,object.access,api.project())){api.toast('The global '+object.kind+' requirements are not met.');return;}api.field().previewAction(object.kind,object.id);api.toast(object.kind==='strength'?'Strength activated. Walk into the boulder to push it.':object.kind==='cut'?'Tree cut down.':'Rock smashed.');return;}
 const r=movementAt(map(),x,y,{openGates:p.openGates,fieldState:p});if(waterAt(map(),x,y)){if(!canUseHM('surf',p,'standard',api.project())){api.toast('The global Surf requirements are not met.');return;}p.surfing=true;api.toast('Surf activated. Move onto the water.');return;}const g=(map().gates||[]).find(g=>gateInteractsAt(g,x,y));if(g){p.openGates.add(g.id);api.refresh();if(g.text)showText(g.name,g.text);else api.toast('Gate opened. It resets when you leave.');return;}const n=api.eventAt?.(x,y,'interact')?.[0]||map().markers.find(n=>n.x===x&&n.y===y&&n.runtime?.enabled!==false&&n.runtime?.action==='dialogue');if(n){if(['sequence','scene'].includes(n.runtime.action))api.runEvent?.(n);else showText(n.title,n.runtime.text);}else api.toast('No authored interaction on the facing tile.',1500);}
 function showText(title,text){const pages=wrapDialogue(text).split('\\p').map(s=>s.replace(/\\n/g,'\n').replace(/\\\$/g,'$')),next=(i=0)=>{api.modal(title,`<div class="dialogue-preview">${esc(pages[i]).replace(/\n/g,'<br>')}</div><p>${i+1} / ${pages.length}</p>`,()=>{if(i+1<pages.length){next(i+1);return false;}},i+1<pages.length?'A · Next':'A · Close');};next();}
 document.querySelectorAll('[data-play-step]').forEach(b=>b.onclick=()=>{const[dx,dy]=b.dataset.playStep.split(',').map(Number);step(dx,dy);});$('#playInteract').onclick=interact;$('#playStop').onclick=stopPlay;document.addEventListener('keydown',e=>{if(!state.play||$('#dialog').open||/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName))return;const d={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]}[e.key];if(d){e.preventDefault();step(...d);}else if(['a','A','Enter',' '].includes(e.key)){e.preventDefault();interact();}else if(e.key==='Escape')stopPlay();});
 return{state,open,walls,movementPanel:(target,close)=>movementPanel({...api,draw:api.draw||api.refresh},state,target,close),inspect:(x,y)=>inspectMovement(api,x,y),fill:(x,y)=>fillMovement(map(),x,y,movementBrush(state)),gates,startPlay,stopPlay,interact,step,gateDialog,paint(x,y){const style=walls().find(w=>w.id===state.wallId);if(!style&&!state.erase)throw Error('Choose a wall style.');if(style)keep('wallStyles',style);paintWall(map(),x,y,style,state.erase);},rectangle(a,b){const style=walls().find(w=>w.id===state.wallId);keep('wallStyles',style);wallRectangle(map(),a,b,style,state.erase);},rule(x,y){setMovement(map(),x,y,movementBrush(state));},tap(x,y,tool){if(tool==='portal')portalTap(x,y);if(tool==='talk'){const n=map().markers.find(n=>n.x===x&&n.y===y);if(n?.runtime?.action==='sequence')api.editEvent?.(n);else api.dialogue(x,y,n,true);}if(tool==='gate'){const g=(map().gates||[]).find(g=>x>=g.x&&x<g.x+g.w&&y>=g.y-g.h+1&&y<=g.y);gateDialog(g,x,y);}if(tool==='play'){if(!state.play){startPlay();return;}const dx=x-state.play.x,dy=y-state.play.y;if(Math.abs(dx)+Math.abs(dy)===1)step(dx,dy);else{if(movementAt(map(),x,y,{openGates:state.play.openGates,fieldState:state.play}).collision){api.toast('Choose a walkable start tile.');return;}state.play.x=x;state.play.y=y;api.refresh();api.toast('Play-check start moved here.',1000);}}}};
}
